const j = $input.first().json;
const body = j.body || j;
const sel = body.selection || {};
const data = {
  type: 'contract-request',
  setup_total: sel.setupTotal || 0,
  retainer_total: sel.retainerTotal || 0,
  net_total: sel.netTotal || 0,
  gross_total: sel.grossTotal || 0,
  setup_items: (sel.setupItems || []).join(', '),
  retainer_items: (sel.retainerItems || []).join(', '),
  submitted_at: body.submittedAt || new Date().toISOString(),
  source: body.source || 'calculator'
};
const tg = `💼 Vertragsanfrage Kalkulator\n\nSetup: ${data.setup_items} (${data.setup_total} EUR)\nRetainer: ${data.retainer_items} (${data.retainer_total} EUR/Mo)\nNetto: ${data.net_total} EUR | Brutto 1. Monat: ${data.gross_total} EUR\n\n→ Stefan: Angebot/DocuSeal vorbereiten.`;
const brain = `[Vertragsanfrage Kalkulator] Netto ${data.net_total} EUR, Brutto ${data.gross_total} EUR. Setup: ${data.setup_items}. Retainer: ${data.retainer_items} (${data.retainer_total}/Mo). Quelle: ${data.source}. Stefan: Kunde kontaktieren, DocuSeal Kombi-Vertrag senden.`;
return [{ json: { ...data, tg_text: tg, brain_message: brain } }];
